// sprites.js — The list of sprite sheets the game loads.
// Each sheet has a PNG (the frames) and a JSON file (frame size, anchor and which
// frames belong to which animation). A character uses one by setting
// `sprite: '<key>'` in data/characters.js; characters without one keep the
// placeholder rectangle art.
//
// Ulric's sheet is generated by tools/sprite-gen/make_ulric.py. You can also
// replace ulric.png with hand-drawn art: keep the frame size and frame order
// listed in ulric.json and nothing else needs to change.

export const SPRITES = {
  ulric: {
    image: 'assets/sprites/ulric.png',
    data: 'assets/sprites/ulric.json',
  },
};
